const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
return [{ json: { prefijo } }];

const j = (n) => $(n).first().json;
const r1 = j('CA86bP_Enviar_1'), v = j('CA86bP_Verificar'), r2 = j('CA86bP_Enviar_2');
const pf = (ok) => (ok ? 'PASA' : 'FALLA');
const casos = [
  { caso: 'C1 envia las 2 alertas pendientes en un solo correo', esperado: 'enviado, 2 alertas, asunto con [PRUEBA]', resultado: pf(r1.estado === 'enviado' && r1.alertas_enviadas === 2 && String(r1.asunto).includes('[PRUEBA]') && String(r1.asunto).includes('2 alertas nuevas')), detalle: JSON.stringify({ estado: r1.estado, alertas_enviadas: r1.alertas_enviadas, asunto: r1.asunto }) },
  { caso: 'C2 las 2 quedan marcadas como enviadas, con fecha', esperado: '2 de 2', resultado: pf(Number(v.enviadas) === 2 && Number(v.total) === 2), detalle: JSON.stringify(v) },
  { caso: 'C3 repetir no reenvia nada', esperado: 'sin alertas pendientes', resultado: pf(r2.estado === 'sin alertas pendientes' && r2.alertas_enviadas === 0), detalle: JSON.stringify({ estado: r2.estado, alertas_enviadas: r2.alertas_enviadas }) },
  { caso: 'C4 el correo llego al buzon de pruebas', esperado: 'Revisar a mano: asunto ' + r1.asunto, resultado: 'MANUAL', detalle: 'Buscar en <CORREO> un correo con ese asunto' },
];
return casos.map((c) => ({ json: c }));
